/**
 * Unified Table Report Print Engine for Retrod POS
 * Matches the official Master List / Table Report standard from Screenshot 1:
 * - Clean property header with logo, title, address, phone & GSTIN on left
 * - Document title, stay/date window subtitle & printed timestamp on right
 * - Subheader metadata bar with Date and Total Records count
 * - Dark Navy (#0f172a) table header with pure white text (#ffffff)
 * - Crisp bordered rows with proper alignments (Currency right-aligned, Dates centered, Text left-aligned)
 * - Optional bold summary totals row
 * - Footer with 'Generated by: Retrod POS' and 'Duty Manager / Signatory' signature line
 */

import { formatDateIndian } from "./dateUtils";
import { getActivePropertyFallback } from "./printReceipt";

export interface PrintReportColumn {
  header: string;
  key?: string;
  align?: "left" | "center" | "right";
  width?: string;
}

export interface PrintReportOptions {
  title: string;
  subtitle?: string;
  dateRange?: string;
  hotelName?: string;
  property?: any;
  alignments?: ("left" | "center" | "right")[];
  columns: (string | PrintReportColumn)[];
  rows: (string | number | boolean | null | undefined)[][] | Record<string, any>[];
  summaryTotals?: (string | number | boolean | null | undefined)[] | Record<string, string | number>;
  notes?: string;
  generatedBy?: string;
}

function escapeHtml(val: any): string {
  if (val === null || val === undefined) return "";
  return String(val)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function isCurrencyCol(colName: string): boolean {
  const name = colName.toLowerCase();
  return ["amount", "price", "total", "cost", "sale", "tax", "gst", "discount", "net", "gross", "due", "paid", "bill", "revenue", "deposit", "₹", "inr"].some(
    (kw) => name.includes(kw)
  );
}

function isDateCol(colName: string): boolean {
  const name = colName.toLowerCase();
  return ["date", "time", "created", "updated", "period", "expiry", "at", "check in", "check out", "slot", "timestamp"].some((kw) => name.includes(kw));
}

/**
 * Generates the unified, professional Master List / Table Report HTML.
 * Directly matches Screenshot 1.
 */
export function generateReportPrintHtml(options: PrintReportOptions): string {
  const prop = getActivePropertyFallback();
  const mergedProp = {
    ...prop,
    ...(options.property || {}),
  };

  const rawPropName = options.hotelName || mergedProp?.name || "Anshu Suite Restaurant";
  const propName = rawPropName.toLowerCase().includes("retrod") ? "Anshu Suite Restaurant" : rawPropName;
  const propAddress = mergedProp?.address && !mergedProp.address.includes("Plot 42")
    ? mergedProp.address
    : "Fortune Tower, Khorda, Odisha, India, - 751001";
  const propPhone = mergedProp?.phone && !mergedProp.phone.includes("2640")
    ? mergedProp.phone
    : "9895898999";
  const propGstin = mergedProp?.gstin && !mergedProp.gstin.includes("27AABCR")
    ? mergedProp.gstin
    : "HGFDRTWC14517713";
  const propLogo = mergedProp?.logo || "";

  const now = new Date();
  const printDateStr = formatDateIndian(now);
  const printTimeStr = now.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit", hour12: true }).toLowerCase();
  const printTimestamp = `${printDateStr}, ${printTimeStr}`;

  // Standardize columns
  const normalizedCols: PrintReportColumn[] = options.columns.map((col, idx) => {
    const overrideAlign = options.alignments ? options.alignments[idx] : undefined;
    if (typeof col === "string") {
      let defaultAlign: "left" | "center" | "right" = "left";
      if (isCurrencyCol(col)) defaultAlign = "right";
      else if (isDateCol(col) || col.toLowerCase().includes("status") || col.toLowerCase().includes("pax") || col.toLowerCase().includes("otp")) {
        defaultAlign = "center";
      }
      return {
        header: col.toUpperCase(),
        align: overrideAlign || defaultAlign,
      };
    }
    let defaultAlign: "left" | "center" | "right" = col.align || "left";
    if (!col.align) {
      if (isCurrencyCol(col.header)) defaultAlign = "right";
      else if (isDateCol(col.header) || col.header.toLowerCase().includes("status")) defaultAlign = "center";
    }
    return {
      header: col.header.toUpperCase(),
      key: col.key,
      align: overrideAlign || defaultAlign,
      width: col.width,
    };
  });

  // Standardize rows
  const rawRows: any[] = options.rows || [];
  const normalizedRows: (string | number)[][] = rawRows.map((row) => {
    if (Array.isArray(row)) {
      return row.map((c) => (c === null || c === undefined ? "" : c));
    }
    return normalizedCols.map((col) => {
      const k = col.key || col.header;
      const val = (row as any)[k] ?? (row as any)[col.header] ?? "";
      return val === null || val === undefined ? "" : val;
    });
  });

  // Standardize summary totals row
  let summaryRow: (string | number)[] | null = null;
  if (options.summaryTotals) {
    if (Array.isArray(options.summaryTotals)) {
      summaryRow = options.summaryTotals.map((c) => (c === null || c === undefined ? "" : c));
    } else {
      summaryRow = normalizedCols.map((col, idx) => {
        if (idx === 0) return (options.summaryTotals as Record<string, string | number>)["Total"] ?? "TOTAL";
        const k = col.key || col.header;
        return (options.summaryTotals as Record<string, string | number>)[k] ?? (options.summaryTotals as Record<string, string | number>)[col.header] ?? "";
      });
    }
  }

  const rawGeneratedBy = options.generatedBy || `${propName} POS`;
  const generatedBy = rawGeneratedBy.toLowerCase().includes("retrod") ? `${propName} POS` : rawGeneratedBy;
  const displayDate = options.dateRange || printDateStr;

  return `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>${escapeHtml(options.title)} - ${escapeHtml(propName)}</title>
  <style>
    @page {
      size: landscape;
      margin: 8mm 10mm;
    }
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
      color: #0f172a;
      background: #ffffff;
      font-size: 11px;
      line-height: 1.4;
      padding: 12px 16px;
    }
    .report-wrapper {
      width: 100%;
      max-width: 1120px;
      margin: 0 auto;
      background: #ffffff;
    }
    .report-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      border-bottom: 2px solid #0f172a;
      padding-bottom: 10px;
      margin-bottom: 12px;
      gap: 16px;
    }
    .header-logo-title {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .header-logo-title img {
      max-height: 48px;
      max-width: 110px;
      object-fit: contain;
    }
    .prop-title {
      font-size: 18px;
      font-weight: 800;
      color: #0f172a;
      letter-spacing: -0.01em;
      text-transform: uppercase;
    }
    .prop-meta {
      font-size: 10px;
      color: #475569;
      margin-top: 2px;
      line-height: 1.35;
    }
    .report-badge-box {
      text-align: right;
      shrink-0;
    }
    .report-main-title {
      font-size: 16px;
      font-weight: 800;
      color: #0f172a;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }
    .report-meta-text {
      font-size: 10px;
      color: #475569;
      margin-top: 3px;
    }
    .report-banner {
      display: flex;
      justify-content: space-between;
      align-items: center;
      background: #f8fafc;
      border: 1px solid #cbd5e1;
      border-radius: 4px;
      padding: 6px 12px;
      margin-bottom: 12px;
      font-size: 11px;
      font-weight: 600;
      color: #0f172a;
    }
    .report-table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 16px;
      font-size: 10.5px;
    }
    .report-table th {
      background: #0f172a !important;
      color: #ffffff !important;
      font-weight: 700;
      text-transform: uppercase;
      font-size: 9.5px;
      letter-spacing: 0.04em;
      padding: 8px 10px;
      border: 1px solid #0f172a;
      white-space: nowrap;
    }
    .report-table td {
      padding: 6.5px 10px;
      border: 1px solid #cbd5e1;
      color: #0f172a;
      vertical-align: middle;
    }
    .report-table tr:nth-child(even) td {
      background: #f8fafc;
    }
    .report-table tr.total-row td {
      background: #f1f5f9 !important;
      font-weight: 800;
      border-top: 2px solid #0f172a;
      border-bottom: 2px solid #0f172a;
      color: #0f172a;
    }
    .report-footer {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      margin-top: 28px;
      padding-top: 14px;
      border-top: 1px dashed #94a3b8;
      font-size: 10.5px;
      page-break-inside: avoid;
    }
    .sig-box {
      border-top: 1px solid #0f172a;
      width: 190px;
      text-align: center;
      padding-top: 4px;
      font-weight: 600;
      color: #0f172a;
    }
    @media print {
      body {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
        padding: 0;
      }
      .report-wrapper {
        max-width: 100%;
      }
    }
  </style>
</head>
<body>
  <div class="report-wrapper">
    <!-- Header -->
    <div class="report-header">
      <div class="header-logo-title">
        ${propLogo ? `<img src="${escapeHtml(propLogo)}" alt="${escapeHtml(propName)}" onerror="this.style.display='none';" />` : ""}
        <div>
          <div class="prop-title">${escapeHtml(propName)}</div>
          <div class="prop-meta">
            ${[
              propAddress,
              propPhone ? `Phone: ${escapeHtml(propPhone)}` : "",
              propGstin ? `GSTIN: ${escapeHtml(propGstin)}` : "",
            ].filter(Boolean).join(" | ")}
          </div>
        </div>
      </div>
      <div class="report-badge-box">
        <div class="report-main-title">${escapeHtml(options.title)}</div>
        ${options.subtitle ? `<div class="report-meta-text">${escapeHtml(options.subtitle)}</div>` : ""}
        <div class="report-meta-text">Printed on: ${escapeHtml(printTimestamp)}</div>
      </div>
    </div>

    <!-- Banner -->
    <div class="report-banner">
      <div><strong>Date:</strong> ${escapeHtml(displayDate)}</div>
      <div><strong>Total Records:</strong> ${normalizedRows.length}</div>
    </div>

    <!-- Data Table -->
    <table class="report-table">
      <thead>
        <tr>
          ${normalizedCols.map((c) => `<th style="text-align: ${c.align || 'left'}; ${c.width ? `width: ${c.width};` : ''}">${escapeHtml(c.header)}</th>`).join("")}
        </tr>
      </thead>
      <tbody>
        ${normalizedRows.length > 0 ? normalizedRows.map((row) => `
          <tr>
            ${row.map((cell, idx) => {
              const align = normalizedCols[idx]?.align || 'left';
              const text = cell !== null && cell !== undefined && cell !== '' ? String(cell) : '—';
              return `<td style="text-align: ${align};">${escapeHtml(text)}</td>`;
            }).join("")}
          </tr>
        `).join("") : `
          <tr>
            <td colspan="${normalizedCols.length}" style="text-align:center; padding: 24px; color:#64748b;">No records found.</td>
          </tr>
        `}
        ${summaryRow ? `
          <tr class="total-row">
            ${summaryRow.map((cell, idx) => {
              const align = normalizedCols[idx]?.align || 'left';
              const text = cell !== null && cell !== undefined && cell !== '' ? String(cell) : '';
              return `<td style="text-align: ${align};">${escapeHtml(text)}</td>`;
            }).join("")}
          </tr>
        ` : ""}
      </tbody>
    </table>

    ${options.notes ? `<div style="font-size:10px; color:#475569; margin-top:6px;"><strong>Notes:</strong> ${escapeHtml(options.notes)}</div>` : ""}

    <!-- Footer -->
    <div class="report-footer">
      <div>Generated by: <strong>${escapeHtml(generatedBy)}</strong></div>
      <div class="sig-box">Duty Manager / Signatory</div>
    </div>
  </div>
</body>
</html>`;
}

let isReportPrintActive = false;

/**
 * Opens a print dialog for the report table using popup window or hidden iframe.
 */
export function openPrintReportTable(options: PrintReportOptions) {
  if (typeof window === "undefined") return;
  if (isReportPrintActive) return;
  isReportPrintActive = true;
  setTimeout(() => {
    isReportPrintActive = false;
  }, 1200);

  let htmlContent = generateReportPrintHtml(options);

  // Inject single-trigger auto-print script
  const reportPrintScript = `
    <script>
      (function() {
        var hasTriggered = false;
        function doSinglePrint() {
          if (hasTriggered) return;
          hasTriggered = true;
          try {
            window.focus();
            window.print();
          } catch (e) {
            console.warn("Report print trigger error:", e);
          }
        }
        if (document.readyState === "complete") {
          setTimeout(doSinglePrint, 250);
        } else {
          window.addEventListener("load", function() {
            setTimeout(doSinglePrint, 250);
          }, { once: true });
        }
      })();
    </script>
  `;

  if (!htmlContent.includes("doSinglePrint")) {
    htmlContent = htmlContent.replace("</body>", `${reportPrintScript}</body>`);
  }

  let printWindow: Window | null = null;
  try {
    printWindow = window.open("", "_blank", "width=1100,height=900");
  } catch (e) {
    printWindow = null;
  }

  if (printWindow) {
    try {
      printWindow.document.open();
      printWindow.document.write(htmlContent);
      printWindow.document.close();
      printWindow.focus();
      return;
    } catch (e) {
      console.warn("Failed to write to print popup, falling back to iframe print", e);
    }
  }

  // Popup blocked? Fallback using hidden iframe
  try {
    const iframe = document.createElement("iframe");
    iframe.style.position = "fixed";
    iframe.style.right = "0";
    iframe.style.bottom = "0";
    iframe.style.width = "0";
    iframe.style.height = "0";
    iframe.style.border = "0";
    document.body.appendChild(iframe);
    const doc = iframe.contentWindow?.document;
    if (doc) {
      doc.open();
      doc.write(htmlContent);
      doc.close();
      setTimeout(() => {
        try {
          iframe.contentWindow?.focus();
          iframe.contentWindow?.print();
        } catch (e) {
          console.error("Iframe print error", e);
        }
      }, 500);
      setTimeout(() => {
        try {
          document.body.removeChild(iframe);
        } catch {}
      }, 60000);
    }
  } catch (e) {
    console.error("Print iframe fallback failed", e);
    alert("Please allow popups to print reports.");
  }
}

